PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://brickschema.org/entity/ontology/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?id WHERE {
  ?z a brick:Zone ; rdfs:label "DataCenter_basement_ZN_6" .
  ?point brick:hasPropertyLocation ?z ;
         brick:hasParameter brick:AirTemperature ;
         ref:hasTimeseriesId ?id .
}

PREFIX brick: <http://brickschema.org/brick#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z WHERE {
  ?z rdfs:label "DataCenter_basement_ZN_6" .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?l WHERE {
  ?z rdfs:label ?l .
  FILTER(?l LIKE "%ZN_6%")
}

PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://brickschema.org/entity/ontology/ref#>
SELECT ?point ?id ?cls WHERE {
  ?point a ?cls ;
         brick:hasLocation brick:ref:Zone_F2_Z06 .
}

SELECT ?point ?prop ?id WHERE {
  ?point brick:hasParameter brick:AirTemperature .
  OPTIONAL{?point ref:hasTimeseriesId ?id}
}
LIMIT 50

